# ====================================================================
# install_av1_pipeline.ps1  V0.24  2026-07-30
# Single-file installer. Contains the pipeline and GUI embedded.
#
# Normally you do not run this directly. Double-click
# "Install AV1 Pipeline.cmd" instead, which calls this.
#
# Manual run:
#   powershell -ExecutionPolicy Bypass -File .\install_av1_pipeline.ps1
#
# On each run: kills running instances, removes old program files,
# wipes the whole program folder, extracts fresh copies, writes a fresh
# config, checks dependencies and skips any already installed, creates
# the launcher and the desktop shortcut, runs verify + selftest.
#
# Every update is a full replace, never a merge over the old files.
# Input and Output are never touched. The old config is backed up.
#
# Do NOT run this elevated when the target lives on a mapped network
# drive. An elevated session does not see the same drive letters.
# ====================================================================

$ErrorActionPreference = "Continue"
function Say($m) { Write-Host ("[setup] " + $m) }

# ---- 0. target layout ---------------------------------------------------
$root = "P:\2_Storage\Film and TV\DownConvert"
$dest = Join-Path $root "Software"
$inp  = Join-Path $root "Input"
$outp = Join-Path $root "Output"

$driveRoot = [System.IO.Path]::GetPathRoot($root)
if (-not (Test-Path $driveRoot)) {
    Say ("drive " + $driveRoot + " is not reachable from this session")
    Say "if P: is a mapped network drive, connect it first, and do not"
    Say "run this installer as administrator (elevated sessions lose"
    Say "mapped drives). then run this again."
    exit 1
}

foreach ($d in @($root, $dest, $inp, $outp)) {
    New-Item -ItemType Directory -Force -Path $d | Out-Null
}
Say "target folder: $dest"

# ---- 1. stop anything already running -----------------------------------
# Get-Process carries no CommandLine on Windows PowerShell 5.1, so the
# match is done through CIM which does carry it on every version
Say "stopping any running pipeline or GUI processes"
Get-CimInstance Win32_Process -Filter "Name='pythonw.exe' OR Name='python.exe'" -ErrorAction SilentlyContinue |
    Where-Object { $_.CommandLine -like "*av1_pipeline*" } |
    ForEach-Object { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue }
Start-Sleep -Seconds 2

# ---- 1a. clean wipe of the program folder -------------------------------
# every update replaces the whole install instead of dropping new files
# on top of old ones. a stale .py or a leftover __pycache__ from an
# earlier version is exactly how a fixed bug comes back to life.
# the settings file is copied aside first so nothing hand-edited is lost.
# Input and Output are never touched.
$cfgPath = Join-Path $dest "av1_pipeline_config.txt"
if (Test-Path $cfgPath) {
    $stamp = Get-Date -Format "yyyyMMdd-HHmmss"
    Copy-Item $cfgPath (Join-Path $dest ("av1_pipeline_config.backup-" + $stamp + ".txt")) -Force
    Say "existing config backed up before the wipe"
}

$wipe = @("av1_pipeline_v0_1.py", "av1_pipeline_gui_v0_1.py",
          "av1_metadata.py", "av1_subs.py",
          "av1_pipeline_config.txt", "gui_settings.json",
          "AV1 Pipeline.cmd", "installed_version.txt")
$removed = 0
foreach ($f in $wipe) {
    $p = Join-Path $dest $f
    if (Test-Path $p) { Remove-Item $p -Force -ErrorAction SilentlyContinue; $removed++ }
}
$pyc = Join-Path $dest "__pycache__"
if (Test-Path $pyc) { Remove-Item $pyc -Recurse -Force -ErrorAction SilentlyContinue; $removed++ }
Say "clean wipe: removed $removed old items from the program folder"

# ---- 2. extract embedded payload files ----------------------------------
Say "extracting pipeline and GUI into $dest"

function Expand-B64Gz($b64, $outPath) {
    $bytes = [System.Convert]::FromBase64String($b64)
    $ms = New-Object System.IO.MemoryStream(, $bytes)
    $gz = New-Object System.IO.Compression.GzipStream($ms, [System.IO.Compression.CompressionMode]::Decompress)
    $fs = [System.IO.File]::Create($outPath)
    $gz.CopyTo($fs)
    $fs.Close(); $gz.Close(); $ms.Close()
}

$PIPE_B64 = ""

$GUI_B64 = ""

$META_B64 = ""

$SUBS_B64 = ""

Expand-B64Gz $PIPE_B64 (Join-Path $dest "av1_pipeline_v0_1.py")
Expand-B64Gz $GUI_B64  (Join-Path $dest "av1_pipeline_gui_v0_1.py")
Expand-B64Gz $META_B64 (Join-Path $dest "av1_metadata.py")
Expand-B64Gz $SUBS_B64 (Join-Path $dest "av1_subs.py")

if (-not (Test-Path (Join-Path $dest "av1_pipeline_v0_1.py"))) { Say "extraction failed"; exit 1 }
Say "files extracted"

# ---- 3. config file -----------------------------------------------------
# the wipe above already removed the old one and kept a timestamped
# backup, so this always lands fresh and matching the version installed
$cfg = @'
﻿# =====================================================================
# AV1 Pipeline config
# =====================================================================
# One setting per line, written as   key = value
# Anything after a # is a comment. Blank lines are ignored.
# Paths are typed plainly. No quotes, no doubled backslashes.
#
# Edit this file with Notepad, save, and the change takes effect on the
# next run. Both the pipeline and the GUI read this same file.
#
# A command line flag always beats what is written here.
# =====================================================================

# Where the source files are read from.
src = P:\2_Storage\Film and TV\DownConvert\Input

# Where the finished files are written.
dst = P:\2_Storage\Film and TV\DownConvert\Output

# Which encoder does the work.
#   auto    test the GPU at startup, fall back to the CPU if it cannot
#           encode AV1. This is the right setting for almost everyone.
#   nvenc   force the GPU. The run stops if it will not encode AV1.
#   svtav1  force the CPU encoder and skip the GPU test.
# Only Ada (RTX 40) and newer NVIDIA cards can encode AV1 at all. On a
# card that can, the GPU encoder still needs an ffmpeg build and a driver
# that agree on the NVENC API version. When they do not, auto keeps the
# batch moving on the CPU and switches back to the GPU on its own as
# soon as the mismatch is resolved.
encoder = nvenc

# CPU encoder speed, 0 slowest and best through 13 fastest and worst.
# 4 to 8 is the useful range. 6 is a good starting point. Every step
# up roughly halves the encode time and costs a little quality.
# Ignored when the GPU encoder is in use.
svtav1_preset = 6

# Folder holding a specific ffmpeg.exe and ffprobe.exe to use instead
# of whichever one is on PATH. Leave blank for normal use.
#
# This is the lever for the NVENC API mismatch. ffmpeg builds sometimes
# ship compiled against an NVENC SDK newer than any released driver
# supports, and the GPU encoder then refuses to start even though the
# card is perfectly capable. Unpack an older ffmpeg build somewhere and
# point this at its bin folder to get the GPU back.
# Example: ffmpeg_dir = C:\ffmpeg-7.1-full_build\bin
ffmpeg_dir =

# Where pipeline.log and av1_trace.log are written.
# Leave this blank for the default, which is a logs folder inside the
# output folder above. Put a path here to send them somewhere else.
log_dir =

# The run stops early if free space on the destination drive falls
# below this many GB. Raise it if the drive fills up mid batch.
min_free_gb = 20

# How much of the processor a run may take, as a percentage of logical
# cores. The work is pinned to that many cores and ffmpeg is told to
# use no more, so the machine stays usable while a batch runs.
#
# On this 16 thread machine:
#     88 = 14 cores (2 left free)   <- current
#     80 = 12 cores (4 left free)
#     75 = 12 cores
#      0 or 100 = take everything
# Encodes are slightly slower for it. Raise it if the desktop is idle
# anyway, lower it if a run still gets in the way.
cpu_max_pct = 88

# Real-ESRGAN model used when a sub-1080 file gets upscaled.
#   realesr-animevideov3    the only model offered
sr_model = realesr-general-x4v3

# Extra data rate for genuinely high quality sources, as a percentage.
# A 4K 10-bit master carries far more real detail than a broadcast rip,
# and squeezing it to the same quality number is what leaves visible
# artifacts in the downscale. Only applies to sources at 2000 lines or
# more that are also 10-bit. 0 turns it off.
hq_source_boost_pct = 30

# ---------------------------------------------------------------------
# Metadata, naming, and tagging
# ---------------------------------------------------------------------
# Look the film up, write its details into the file, and rename it.
# The folder structure is never changed; only the file is renamed, so a
# file that escapes its folder still identifies itself.
metadata_enable = 1

# Free API key from https://www.themoviedb.org/settings/api
# Without one, lookups are skipped and files keep their original names.
tmdb_api_key = 4128f0600ff5a5b2846859615b173f83

# Rename finished files from the metadata. 0 tags only.
rename_files = 1

# Confirm the identification with pictures, not just text. Frames are
# sampled from the finished file and compared against TMDB's backdrops
# and episode stills using a perceptual hash. A close match is real
# evidence the file is what the name claims.
#
# There is no service that identifies a film from a frame - the tools
# that appear to are web apps with no API - so this is done locally
# against TMDB's own images. It raises confidence and never rejects a
# match: a miss usually means the backdrops are promotional stills
# rather than real frames, which proves nothing either way.
metadata_verify_frames = 1

# Write a readable .info file beside each finished video containing the
# identification, the verification result, the source details and every
# processing decision. Named to match the video so the two pair up in a
# directory listing.
metadata_info_file = 1

# Shape:  Title-(Year)-Franchise-AV1_1080p.mkv
#    TV:  Show-(Year)-S05E01-Episode_Title-AV1_1080p.mkv
# Underscores instead of spaces, because linux command lines hate spaces.
name_underscores = 1
name_episode_title = 1
name_tech_suffix = 1

# ---------------------------------------------------------------------
# Subtitle generation
# ---------------------------------------------------------------------
# When a language is missing, generate it. English is transcribed from a
# strongly dialogue-boosted mix of the English audio, which is also kept
# as its own output track. Japanese is transcribed from the Japanese
# audio when one exists, and translated from the English subtitles when
# it does not. Timings come from the file's own audio, so a generated
# track is always in sync.
subs_generate = 1

# How long a slice of audio whisper chews at a time, in seconds. 0 uses
# ffmpeg's own default of 3. Measured on 60 seconds of speech, 20 was
# both quicker than the default (3.3 s against 5.6 s) and produced
# tidier, better merged subtitles, so 20 is the setting here.
whisper_queue = 20

# Voice activity detection. Feeds whisper only the parts that actually
# contain speech, so it never sees the silence it otherwise fills with
# invented lines like "thank you for watching". Needs a ggml-silero
# model file sitting beside the whisper model.
#
# OFF by default because it is expensive. Measured on the same 60
# seconds: 25.4 s with it against 5.6 s without, for a transcript that
# was otherwise identical. On a two hour film that is the difference
# between minutes and hours. The trailing-repeat trimmer and the
# duration clamp already remove invented lines afterwards for free.
# Turn it on if a particular file keeps producing rubbish over its
# quiet passages.
whisper_vad = 0

# Folder holding the whisper ggml model. The installer puts one here.
whisper_model_dir = C:\ProgramData\whisper

# Blank picks the best model present. ggml-large-v3-turbo.bin is the
# default and the best quality for the time it takes.
whisper_model =

# Run whisper on the graphics card. Much faster when supported.
whisper_gpu = 1

# Translation, used only when there is no Japanese audio to transcribe.
# Without one of these, English subtitles are still generated; Japanese
# ones are simply skipped.
#
#   argos   FULLY LOCAL. No key, no network, no cost. INSTALLED AND
#           WORKING on this machine: argostranslate 1.11.0 with the
#           en->ja model, measured at 0.32 s a line, so about 2.4
#           minutes for a typical episode.
#   deepl   paid web service, charges per token. Refused on cost.
#   openai  any OpenAI-compatible chat endpoint, including a local LLM
#           server; set translate_endpoint to something like
#           http://localhost:11434/v1 and put any placeholder in
#           translate_key.
#
# A NOTE ON QUALITY, because it matters more than the plumbing: argos
# gets roughly half of it right. Measured on plain test sentences,
# "Where are the keys?" and "It is snowing outside" came back correct,
# but "Good evening" became the time of day rather than the greeting,
# and "he would be here by seven" became "here with seven people".
# On a whisper transcript it is a machine translation of a machine
# transcription, and the errors compound. Treat the Japanese track as a
# rough convenience, not a subtitle anyone should rely on.
#
# Set this back to deepl to switch it off.
translate_provider = argos
translate_key =
translate_endpoint =
translate_model =

# How often the audio sync check reports while it walks the file, in
# windows. Lower means more frequent. 0 turns the running report off.
sync_report_every = 12

# Offset in milliseconds that earns a warning during that check.
sync_warn_ms = 120

# Which subtitle languages to keep. Blank keeps all. Subtitle tracks
# whose size the container does not report are always dropped: copying
# one of those deadlocks the muxer part way through an encode.
subs_langs = eng,en,jpn,ja,jp,und

# Shifts every computed quality number. Negative means better quality
# and larger files; each step is worth roughly 12 percent bitrate, so
# -2 is about +26 percent and -4 about +59 percent.
#
# This is the only quality lever NVENC has left. Preset, tune, lookahead
# and adaptive quantisation are already at their maximum settings, so
# there is nothing else to turn up: the remaining choice is bitrate.
# If you want genuinely better quality per byte rather than more bytes,
# set encoder = svtav1 instead, which is measurably more efficient than
# any hardware encoder but takes hours per film rather than minutes.
cq_offset = 0

# How far the finished picture may differ in length from the source
# before the file is called failed, in seconds.
#
# Measured video track against video track, not container against
# container: a Matroska container reports the length of its LONGEST
# track, and a signs or commentary subtitle running past the credits
# used to fail perfectly good encodes - for a track the pipeline had
# deliberately dropped.
#
# 1 second flat. The old rule scaled with runtime and allowed a 92
# minute film to drift 27 seconds, which is a whole scene.
duration_tolerance_sec = 1.0

# Low resolution sources inflate badly when upscaled to 1080 lines,
# because the bitrate ends up describing the upscale rather than the
# film. A 512x288 AVI measured 0.69 GB in, 2.66 GB out. These trim the
# quality number back for that class ONLY; nothing at 720 lines or
# above is affected.
#   lowres_trim_h   source height at or below which this applies
#   lowres_cq_trim  how many steps to add (higher = smaller file)
#   lowres_cq_ceil  the ceiling for this class alone, deliberately
#                   above the library-wide one, because the detail up
#                   there was invented by the scaler, not filmed
# Measured on a 512x288 source: cq 28 = 418 pct of source, cq 30 = 333
# pct, cq 33 = 240 pct, cq 36 = 173 pct, cq 39 = 126 pct.
# Set lowres_cq_trim = 0 to switch the whole thing off.
lowres_trim_h = 576
lowres_cq_trim = 8
lowres_cq_ceil = 36

# Sources with at least this many lines of real picture keep the quality
# number their tier earned, even when they are upscaled to 1080.
#
# upscale_cq exists because detail invented by a scaler is not worth
# spending bits on, which is true of a 512x288 AVI. It is NOT true of a
# 1920x800 scope feature - that is a full Blu-ray rip which simply has
# fewer than 1080 lines because of its aspect ratio. The Simpsons Movie
# arrived at tier HIGH, 9.86 Mbps, 0.268 bits per pixel, and went out at
# 0.04 bpp purely because 800 is less than 1080. It blocked visibly.
#
# Set to 0 to go back to treating every upscale the same.
upscale_cq_max_h = 720

# ---------------------------------------------------------------------
# Target resolution
# ---------------------------------------------------------------------
# How many lines of ACTUAL PICTURE to aim for. Bars are never counted,
# so a letterboxed film is measured on the picture inside them.
#   1080   the standard, and the default
#   2160   4K, opt-in
# 2160 only produces a 4K master when the source is ALREADY close to 4K.
# A DVD or a 1080p Blu-ray in a 4K batch is still finished at 1080p: the
# AI upscaler never aims above 1080 lines, because inventing 4K detail
# from a smaller source bakes artifacts in permanently.
#
# The GUI dropdown starts from this value every time the window opens
# and a change there applies to that run only, exactly like no_sr and
# sdr_to_hdr. This is library-wide policy, not a per-run preference.
target_res = 1080

# What counts as "close to 4K", and so eligible for a 4K master.
# Measured on the stored WIDTH rather than the height, because width
# survives letterboxing: a 2.39:1 UHD is 3840x1608 once the bars come
# off, which a height test would wrongly reject. uhd_min_pixels is the
# second guard so a 3840x1080 ultrawide cannot qualify on width alone.
uhd_min_width = 3000
uhd_min_pixels = 5500000

# Real picture within this percentage of 2160 lines is brought UP to
# 2160 exactly; anything further below keeps its native size. A 1.85:1
# UHD has 2076 real lines, which is 96.1 pct, so it pads. A 2.39:1 scope
# title has 1608 lines, which is 74.4 pct, so it stays as it is rather
# than being stretched to a line count it was never shot at.
uhd_pad_band_pct = 10

# Size ceiling for a 4K master, in GB. SOFT on purpose. The target is
# the smaller of the source's own size and this number, so a 6 GB web-dl
# aims at 6 GB rather than being inflated to fill the allowance.
#
# If holding the quality floor below still predicts an oversized file,
# THE FILE WINS and the log says so loudly. Picture quality outranks
# size. For scale: 10 GB on a 100 minute film is about 0.055 bits per
# pixel, against the 0.194 the 1080p standard spends - roughly a third.
uhd_max_gb = 10.0

# The quality floor, expressed as the worst CQ the size budget may drive
# to. CQ rises to fit the budget and stops here.
#
# 32 is what lets the 10 GB cap actually work on a real remux: on a 101
# minute UHD it predicts about 9.6 GB all in. A floor of 30 stops around
# 12.4 GB, which makes the cap close to decorative. Raise this to protect
# picture harder and accept bigger files; lower it to hold the size down
# at the cost of picture.
uhd_cq_ceil = 32

# Bits per second left for audio, subtitles and container overhead when
# working out how many bits the video may have. Four Opus tracks on a
# surround source run to about 2 Mbps.
uhd_overhead_mbps = 2.5

# Calibration constant for predicting output size from CQ without a test
# encode, in bits per pixel per second at CQ 27.
#
# MEASURED on this machine over five 20 second windows spread across a
# UHD remux at 3996x2160: 23.62, 25.54, 24.71, 22.34, 23.48 Mbps, mean
# 23.94, spread about 7 pct. That is ONE title, and 1988 film stock with
# real grain is expensive to encode, so a clean modern digital source
# will land under this figure and a busier one over it.
#
# Note also that the CQ curve is NOT a clean exponential: measured on the
# same file, CQ 21 = 50.20 Mbps, 23 = 30.27, 25 = 30.08, 27 = 24.71,
# 29 = 18.27, 31 = 13.34. There is a real plateau at 23-25. So this
# predicts a sensible starting CQ rather than promising a final size.
#
# Set to 0 to switch size prediction off, in which case CQ comes from the
# tier table alone and only the VBV cap constrains the result.
uhd_bpp_ref = 0.1157

# Artifact repair for damaged 4K sources.
#   auto    repair when the source lands in artifact_repair_tiers.
#           Default.
#   off     never
#   weak    always, gentle
#   strong  always, aggressive
# The filter is ffmpeg's deblock. It is the ONLY candidate that is both
# 10-bit clean and fast enough at 4K: fspp, pp7 and uspp are all 8-bit
# only and would drag the entire filter graph down to 8 bits, and spp
# costs between 12 and 110 hours a film. All measured, not assumed.
#
# Gated on the existing bits-per-pixel tier table rather than on a
# blockiness detector. ffmpeg's blockdetect was measured for this job and
# is unusable: on a fair bitrate ladder it scored a transparent 8000k
# encode at 1.6222, a 600k one at 1.3681 and a wrecked 300k one at
# 1.5613. Non-monotonic, so no threshold separates good from bad.
#
# Costs roughly 40 minutes on a 110 minute film at 4K.
artifact_repair = auto
artifact_repair_tiers = low,awful

# When deband runs.
#   auto    only on sources under 10-bit, where 8-bit quantisation
#           banding actually exists to be fixed. Default.
#   always  on everything. Costs real CPU at 4K, and on a clean 10-bit
#           master it adds dither rather than removing steps.
#   off     never.
# This is a quality choice, not a speed one. If you see banding in dark
# gradients on a 4K encode, set this to always and compare.
deband_mode = auto

# Who assembles the finished file. With this on, ffmpeg produces only
# the video and audio and mkvmerge adds the subtitles, fonts and
# chapters afterwards. mkvmerge is purpose-built for Matroska, and
# three of the nastiest faults this pipeline has had all lived in
# ffmpeg's Matroska writer: a subtitle deadlock that froze 4K remuxes,
# an attachment bug that made healthy encodes look hung, and a subtitle
# running past the end of the picture. Set to 0 to go back to the
# single ffmpeg command. Ignored if mkvmerge is not installed.
mux_mkvmerge = 1

# Hardware video decode. auto tests it at startup and uses it if the
# card supports it, which is the single biggest speed gain on 4K:
# decoding 4K HEVC in software pins the CPU and leaves the GPU encoder
# waiting for frames. cuda forces it, none disables it.
hwaccel = auto

# Fixed audio layout. Every kept track is re-encoded to Opus in this
# exact order, and everything else is dropped, including commentary and
# audio-description tracks:
#   1 English stereo downmix      2 Japanese stereo downmix
#   3 English original surround   4 Japanese original surround
audio_fixed_layout = 1

# Opus quality for the original surround tracks, kbps per channel.
# 128 is well past transparent; 80 is already hard to tell from source.
audio_opus_per_ch = 128

# Which audio languages to keep. A Blu-ray remux ships every dub, and
# carrying fifteen of them means fifteen concurrent encoders and
# gigabytes of audio nobody plays. Blank keeps every language.
audio_langs = eng,en,jpn,ja,jp

# For English, keep only the generated stereo downmix rather than the
# surround masters. Any English 2 channel track already in the source is
# kept as well. Set to 0 to keep the English surround tracks too.
audio_eng_stereo_only = 1

# List the stereo downmix first, so players open on it.
audio_mix_first = 1

# Seconds with no forward progress before an encode is treated as hung
# and killed. ffmpeg can keep reporting a slowly falling speed while the
# output position never moves, which looks like a slow encode but is
# actually a stall. 0 disables the watchdog.
stall_timeout_sec = 420

# Keep every audio track, ordered with English first. 0 keeps only the
# single best track, which is how older versions behaved.
audio_keep_all = 1

# Add a stereo downmix of any English surround track, with the centre
# channel lifted for dialogue. Useful on headphones and TV speakers.
# The surround track stays the default; this one is there to be chosen.
audio_add_stereo_mix = 1

# Centre channel lift in that downmix. 1.0 is the normal downmix, which
# already lifts centre 30 percent. 1.25 lifts it further again.
audio_mix_centre = 1.25

# Dialogue enhancement strength on the downmix, 0 to 3. ffmpeg's
# dialoguenhance filter. 0 turns it off.
audio_mix_enhance = 0.6

# Add a blank subtitle track first so players open with subtitles off
# instead of showing whichever track happened to be first in the source.
subs_blank_first = 1

# What happens to the audio track.
#
#   auto    keep the original stream untouched when it is already a
#           codec every player handles (AC3, E-AC3, AAC, DTS, TrueHD,
#           FLAC, MP3, Opus, PCM), and convert anything more awkward to
#           Opus. This is the default and it loses nothing on a normal
#           DVD or Blu-ray rip.
#   copy    never re-encode. Truest to the source. A very old or unusual
#           codec may then need transcoding at playback time.
#   opus    always convert to Opus. Best quality for the size of any
#           current lossy codec, and handles surround properly.
#   aac     always convert to AAC. Only worth it for a player that
#           refuses Opus.
#
# Re-encoding audio that is already lossy loses a little every time, so
# copying is the honest answer whenever the source codec is fine.
audio_mode = opus

# Set to 1 to fold surround down to stereo. Off by default, so a 5.1
# track stays 5.1. Turning this on forces a re-encode, because filters
# cannot be applied to a copied stream.
audio_downmix = 0

# Set to 1 to run a noise reducer over badly starved audio. Off by
# default. It only engages below about 64 kbps a channel, so a normal
# AC3 5.1 track at 448k is never touched. Leave it off unless you are
# working with genuinely poor sources; it smears detail on anything else.
audio_denoise = 0

# ---------------------------------------------------------------------
# The 1080p standard
# ---------------------------------------------------------------------
# The target is 1080 lines of ACTUAL PICTURE, measured after black bars
# are cropped away. Width follows whatever aspect the film is in, so a
# 2.39:1 scope film lands at 2580x1080 and a 16:9 one at 1920x1080.
# Nothing is ever stored as black bars.
#
# Black bars are found by sampling across the whole file and taking the
# shape the film spends most of its time in. Top, bottom, side, and
# postage-stamp bars are all handled. If a film genuinely changes aspect
# part way through, the dominant ratio wins and the log says so.
#
# What happens to a file then follows from the cropped picture height:
#   under 1080 lines   upscaled, and eligible for the AI upscaler
#   exactly 1080       left alone, with a contrast adaptive sharpen
#   over 1080          downscaled, which oversamples and is already sharp
# A 1080p file with bars has less than 1080 lines of real picture, so it
# gets upscaled like any other short source.

# Contrast Adaptive Sharpen strength, 0 to 1. Only used where no rescale
# happens, since a resize brings its own sharpness change. This is the
# FidelityFX CAS algorithm, but ffmpeg runs it on the CPU, so it works
# the same on any graphics card. 0 turns it off.
cas_strength = 0.30

# Saturation lift for standard definition sources, 1.0 is unchanged.
# This is a deliberate look change rather than a restoration, so keep it
# modest. Only applied to sources at or below 720 lines.
sd_saturation = 1.06

# How much of the AI upscale to keep, 0 to 100.
#
# Real-ESRGAN looks at one frame at a time and has no memory of the
# frame before it, so it invents slightly different detail every frame.
# On a still background that reads as crawling or shimmering. Tools like
# Topaz avoid it by feeding the model several frames at once, which is a
# property of the model and cannot be added here.
#
# What this does instead is blend the model output back towards a plain
# lanczos upscale. 100 is the raw model with all its shimmer, 0 is no AI
# at all, 50 keeps half the invented detail and roughly halves the
# flicker with it. Lower this further if backgrounds still crawl.
sr_strength = 50

# Temporal stabiliser applied after the blend. Averages each pixel
# across neighbouring frames only while the difference stays small, so
# still backgrounds settle while anything actually moving passes through
# untouched. Set to 0 to turn it off.
sr_stabilise = 1

# Fast local folder for the upscaler's frame files. Leave blank to use
# the destination.
#
# WHERE EVERY INTERMEDIATE FILE GOES. This must be a LOCAL disk.
#
# It is no longer only the upscaler's frames. As of 0.24 this governs
# all working material:
#   - upscaler PNG frames, and the per-chunk encoded pieces
#   - the elementary streams pulled out for a Dolby Vision strip, which
#     are the size of the film TWICE OVER, plus the remux as a third
#     copy - about 145 GB of traffic for a single 50 GB title
#   - extracted ASR audio for whisper
#   - the video+audio intermediate that mkvmerge reads back
#   - frames sampled for the visual check, tag XML, the blank subtitle
#
# ONLY THE FINISHED OUTPUT IS WRITTEN TO THE DESTINATION. That matters
# because the destination here is a network-backed DrivePool, and
# Microsoft document that concurrent access to a file on a network drive
# serialises behind a Csc.sys resource lock, stalling every application
# waiting on that path - which is what "the whole desktop froze" looks
# like from the outside.
#
# Size it for the largest title: a Dolby Vision strip needs roughly 3.2
# times the source size, and the pipeline refuses the file with a clear
# message rather than filling the disk half way through.
#
# Leaving this blank falls back to the destination's .tmp, which is the
# old behaviour and is exactly what caused the trouble. The startup
# banner warns if it is unset.
# Example: sr_tmp_dir = C:\av1_scratch
sr_tmp_dir = S:\temp

# Upscale factor for the AI model.
#   0  pick the smallest the model has that clears 1080 lines
#   2  force x2
# The cost is quadratic. A 528 line film at x4 becomes 2112 lines and
# then most of those pixels are thrown away scaling back down to 1080;
# x2 lands at 1056 and the last 2 percent is a near-free resize. Four
# times fewer pixels to compute.
#
# NOTE: only realesr-animevideov3 has x2 and x3. realesrgan-x4plus is a
# 4x model and nothing else, so forcing x2 with it will warn and use x4.
sr_scale = 2

# Tile size handed to the upscaler, in pixels.
#   0  work it out from the video memory actually free at the time
#   N  force that tile
#
# Leave this at 0. Memory cost goes as tile SQUARED and again as scale
# SQUARED, so a fixed number that is fine at x2 can be several times
# over the card at x4. A 1024 tile at x4 is about 11 GB on its own.
sr_tile = 0

# How much of the card a run may aim at in total, in MB, and how much
# to hold back.
#
# The upscaler does NOT have the card to itself: the encode of the
# previous file runs alongside it and was measured at 2.3 to 3.4 GB,
# and the desktop wants some too. The reserve is what keeps that from
# becoming a crash. The tile is then sized from whatever is genuinely
# free at the moment the upscale starts, less the reserve, so a busy
# card simply gets a smaller tile instead of falling over.
#
# If it still runs out, the pipeline halves the tile and retries rather
# than failing the file, and the log says where it settled.
sr_vram_mb = 15000
# Held back for the NVENC session that encodes each upscaled chunk while
# the model is still resident. Measured at 2.3 to 3.4 GB, so 3400.
sr_vram_reserve_mb = 3400

# ---------------------------------------------------------------------
# GPU safety
# ---------------------------------------------------------------------
# HARD ceiling on TOTAL video memory in use, as a percentage of the card.
# This is the line that must never be crossed. Crossing it does not fail
# a file politely - it resets the display driver, and on 2026-08-06 it
# took the whole machine down: six nvlddmkm errors at 18:21, then an
# unexpected shutdown.
#
# 98 leaves the desktop compositor and anything else running room. Set
# lower if you use the machine while it works. 100 is refused.
gpu_max_pct = 98

# Largest tile the upscaler may be given, whatever the arithmetic says.
# 896 at x4 was MEASURED safe alongside a running encode, at about
# 8.3 GB. The budget picked 992 on 2026-08-06 and the driver fell over
# 31 minutes later. The underlying cost model comes from ncnn's own
# auto-select thresholds, which are heuristics rather than measured
# allocations, so it is not trusted past what has actually been tried.
sr_tile_max = 896

# Seconds to let the driver hand video memory back after a process is
# killed. nvidia-smi keeps reporting the old figure for a moment, and
# sizing the next job against that stale number turns one over-commit
# into two.
gpu_settle_sec = 5

# How long to wait for video memory before giving up on a file and
# moving on to the next. Never blocks forever; never barges in either.
gpu_wait_sec = 300

# ---------------------------------------------------------------------
# Load ceilings, after three hard machine freezes
# ---------------------------------------------------------------------
# On 2026-08-06, and twice on 2026-08-09, the whole machine locked up.
# Every one of them recorded Kernel-Power 41 with BugcheckCode=0,
# PowerButtonTimestamp=0, no crash dump and no WHEA hardware error.
# That combination means Windows did NOT crash - there was no blue
# screen and nobody held the power button. The kernel simply stopped
# running, which is what heat, power delivery or memory instability do.
# Software cannot fix that. What it CAN do is stop standing on the
# limit, which is what everything below is for.
#
# Temperature the card must come back under before more work is added.
# 0 disables the check.
gpu_temp_max_c = 80
gpu_cool_sec = 15

# Seconds to idle between upscaler chunks. Without this the upscale
# holds the GPU, the CPU and the disk at full tilt for eleven hours
# without a break. Costs a few percent of throughput.
sr_chunk_pause_sec = 2.0

# Threads for load : process : save. The tool's own default is 1:2:2,
# and with thousands of small PNG frames one decode thread leaves the
# card waiting on the disk instead of computing.
sr_threads = 4:4:4

# Set to 1 to skip Real-ESRGAN entirely and upscale with lanczos.
# Much faster, noticeably softer. Leave at 0 for normal runs.
no_sr = 0

# Set to 1 to expand SDR sources into HDR10 color. Off by default
# because it changes the look of every SDR file in the batch.
sdr_to_hdr = 0
'@
Set-Content -Path $cfgPath -Value $cfg -Encoding UTF8
Say "wrote config file: $cfgPath"
$stampLines = @(
    ("AV1 Pipeline V0.24 installed " + (Get-Date -Format "yyyy-MM-dd HH:mm:ss")),
    "Settings from any earlier install are kept in av1_pipeline_config.backup-*.txt"
)
Set-Content -Path (Join-Path $dest "installed_version.txt") -Value $stampLines -Encoding ASCII

# ---- 4. winget toolchain ------------------------------------------------
Say "checking ffmpeg"
winget install --id Gyan.FFmpeg -e --accept-source-agreements --accept-package-agreements
Say "checking Python"
winget install --id Python.Python.3.12 -e --accept-source-agreements --accept-package-agreements
Say "checking MKVToolNix"
winget install --id MoritzBunkus.MKVToolNix -e --accept-source-agreements --accept-package-agreements

# ---- 5. refresh PATH ----------------------------------------------------
$env:Path = [Environment]::GetEnvironmentVariable("Path", "Machine") + ";" + [Environment]::GetEnvironmentVariable("Path", "User")
$pycmd = Get-Command python -ErrorAction SilentlyContinue
if (-not $pycmd -or $pycmd.Source -like "*WindowsApps*") {
    Say "python does not resolve yet; close this window, open a new one, run the installer again"
    exit 1
}

# ---- 6. python deps -----------------------------------------------------
Say "checking numpy and scipy"
python -m pip install --upgrade pip 2>$null
python -m pip install numpy scipy guessit

# ---- 7. dovi_tool -------------------------------------------------------
# third party binaries stay on the local C: drive on purpose; they get
# hit constantly during a batch and P: may be a network path
$dvdir = "C:\ProgramData\dovi_tool"
$dvexe = Join-Path $dvdir "dovi_tool.exe"
if (Test-Path $dvexe) { Say "dovi_tool present" }
else {
    Say "fetching dovi_tool"
    try {
        $r = Invoke-RestMethod https://api.github.com/repos/quietvoid/dovi_tool/releases/latest
        $a = $r.assets | Where-Object { $_.name -like "*x86_64-pc-windows*" } | Select-Object -First 1
        Invoke-WebRequest $a.browser_download_url -OutFile "$env:TEMP\dovi.zip"
        New-Item -ItemType Directory -Force -Path $dvdir | Out-Null
        Expand-Archive "$env:TEMP\dovi.zip" -DestinationPath $dvdir -Force
        if (-not (Test-Path $dvexe)) {
            $f = Get-ChildItem $dvdir -Recurse -Filter dovi_tool.exe | Select-Object -First 1
            if ($f) { Move-Item $f.FullName $dvexe -Force }
        }
        $up = [Environment]::GetEnvironmentVariable("Path", "User")
        if ($up -notlike "*dovi_tool*") { [Environment]::SetEnvironmentVariable("Path", $up + ";" + $dvdir, "User") }
    } catch { Say ("dovi_tool fetch failed: " + $_.Exception.Message) }
}

# ---- 8. realesrgan-ncnn-vulkan ------------------------------------------
$srdir = "C:\ProgramData\realesrgan"
$srexe = Join-Path $srdir "realesrgan-ncnn-vulkan.exe"
if (Test-Path $srexe) { Say "realesrgan present" }
else {
    Say "fetching realesrgan-ncnn-vulkan"
    try {
        $url = "https://github.com/xinntao/Real-ESRGAN/releases/download/v0.2.5.0/realesrgan-ncnn-vulkan-20220424-windows.zip"
        Invoke-WebRequest $url -OutFile "$env:TEMP\realesrgan.zip"
        New-Item -ItemType Directory -Force -Path $srdir | Out-Null
        Expand-Archive "$env:TEMP\realesrgan.zip" -DestinationPath $srdir -Force
        if (-not (Test-Path $srexe)) {
            $f2 = Get-ChildItem $srdir -Recurse -Filter realesrgan-ncnn-vulkan.exe | Select-Object -First 1
            if ($f2) { Get-ChildItem $f2.DirectoryName | Move-Item -Destination $srdir -Force -ErrorAction SilentlyContinue }
        }
        $up2 = [Environment]::GetEnvironmentVariable("Path", "User")
        if ($up2 -notlike "*realesrgan*") { [Environment]::SetEnvironmentVariable("Path", $up2 + ";" + $srdir, "User") }
    } catch { Say ("realesrgan fetch failed: " + $_.Exception.Message) }
}

# ---- 8b. whisper model for subtitle generation --------------------------
# ggml model from whisper.cpp. large-v3-turbo is the best quality per
# second of runtime; about 1.6 GB. Skipped if already present.
$wdir = "C:\ProgramData\whisper"
$wmodel = Join-Path $wdir "ggml-large-v3-turbo.bin"
if (Test-Path $wmodel) { Say "whisper model present" }
else {
    Say "fetching whisper model (about 1.6 GB, one time)"
    try {
        New-Item -ItemType Directory -Force -Path $wdir | Out-Null
        $wurl = "https://huggingface.co/ggerganov/whisper.cpp/resolve/main/ggml-large-v3-turbo.bin"
        Invoke-WebRequest $wurl -OutFile $wmodel
        if ((Get-Item $wmodel).Length -lt 100000000) {
            Say "whisper model download looks truncated, removing it"
            Remove-Item $wmodel -Force -ErrorAction SilentlyContinue
        }
    } catch { Say ("whisper model fetch failed: " + $_.Exception.Message) }
}

# ---- 9. launcher inside the Software folder -----------------------------
# pythonw runs the GUI with no console window sitting behind it
$pyw = (Get-Command pythonw -ErrorAction SilentlyContinue).Source
if (-not $pyw) { $pyw = $pycmd.Source }
$launcher = Join-Path $dest "AV1 Pipeline.cmd"
$lines = @(
    '@echo off',
    'rem Double-click to open the AV1 Pipeline window.',
    'cd /d "%~dp0"',
    ('start "" "' + $pyw + '" "%~dp0av1_pipeline_gui_v0_1.py"')
)
Set-Content -Path $launcher -Value $lines -Encoding ASCII
Say "launcher written: $launcher"

# ---- 10. desktop shortcut -----------------------------------------------
$ws  = New-Object -ComObject WScript.Shell
$lnk = $ws.CreateShortcut("$env:USERPROFILE\Desktop\AV1 Pipeline.lnk")
$lnk.TargetPath = $pyw
$lnk.Arguments = '"' + (Join-Path $dest "av1_pipeline_gui_v0_1.py") + '"'
$lnk.WorkingDirectory = $dest
$lnk.Save()
Say "desktop shortcut created"

# ---- 11. verify ---------------------------------------------------------
Say "verify:"
ffmpeg -version | Select-Object -First 1
python --version
$mkv = (Get-Command mkvmerge -ErrorAction SilentlyContinue).Source
if (-not $mkv) { $mkv = "C:\Program Files\MKVToolNix\mkvmerge.exe" }
if (Test-Path $mkv) { & $mkv --version } else { Say "mkvmerge NOT found" }
if (Test-Path $dvexe) { & $dvexe --version } else { Say "dovi_tool NOT found" }
if (Test-Path $srexe) { Say "realesrgan present at $srexe" } else { Say "realesrgan NOT found" }
if (Test-Path $wmodel) { Say ("whisper model: " + [math]::Round((Get-Item $wmodel).Length/1GB,2) + " GB") } else { Say "whisper model NOT found; subtitle generation will be skipped" }
ffmpeg -hide_banner -filters | Select-String whisper
python -c "import numpy, scipy; print('numpy', numpy.__version__, 'scipy', scipy.__version__)"
ffmpeg -hide_banner -encoders | Select-String av1_nvenc
ffmpeg -hide_banner -filters | Select-String "libvmaf|libplacebo|zscale|afftdn"
Say "selftest:"
python (Join-Path $dest "av1_pipeline_v0_1.py") --selftest

# ---- 12. summary --------------------------------------------------------
Say "----------------------------------------------------------------"
Say "input folder:  $inp"
Say "output folder: $outp"
Say "config file:   $cfgPath"
Say "trace log:     $dest\av1_trace.log"
Say "launch from the AV1 Pipeline desktop shortcut, or from"
Say "$launcher"
